package net.oceancanvas.mod.diagnostic;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class OceanCanvasRawTickSpansTest {
 @Test void exactPartitionAndSequence(){var o=new OceanCanvasRawTickSpans(2);o.begin(7,100);o.flattener(30_000_100,50_000_100);var s=o.end(80_000_100);assertEquals(7,s.sequence());assertEquals(80_000_000,s.rawNs());assertEquals(30_000_000,s.beforeFlattenerNs());assertEquals(20_000_000,s.flattenerNs());assertEquals(30_000_000,s.afterFlattenerNs());assertNull(o.end(90_000_100));}
 @Test void thresholdAndBackwardClock(){var o=new OceanCanvasRawTickSpans(2);o.begin(1,1);assertNull(o.end(50_000_001));o.begin(2,100);assertNull(o.end(99));o.begin(3,1);assertNotNull(o.end(50_000_002));}
 @Test void absentOrInvalidFlattenerIsUnavailableNotZero(){var o=new OceanCanvasRawTickSpans(2);o.begin(1,100);o.flattener(99,200);assertEquals(-1,o.end(60_000_100).flattenerNs());o.begin(2,0);o.flattener(40_000_000,80_000_000);assertEquals(-1,o.end(60_000_000).beforeFlattenerNs());}
 @Test void eventLimitAndReset(){var o=new OceanCanvasRawTickSpans(1);o.begin(1,0);assertNotNull(o.end(60_000_000));o.begin(2,0);assertNull(o.end(60_000_000));assertTrue(o.snapshot().contains("dropped=1"));o.reset();o.begin(3,0);assertNotNull(o.end(60_000_000));assertTrue(o.snapshot().contains("dropped=0"));}
 @Test void actualJfrEventCarriesRawMonotonicSpans() throws Exception {var file=java.nio.file.Files.createTempFile("oc-raw-span-", ".jfr");try(var recording=new jdk.jfr.Recording()){recording.enable("oceancanvas.RawTickSpan");recording.start();var o=new OceanCanvasRawTickSpans(1);o.begin(19,10);o.flattener(20_000_010,40_000_010);o.finishAndRecord(70_000_010);recording.stop();recording.dump(file);var events=jdk.jfr.consumer.RecordingFile.readAllEvents(file).stream().filter(e->e.getEventType().getName().equals("oceancanvas.RawTickSpan")).toList();assertEquals(1,events.size());assertEquals(19,events.getFirst().getLong("sequence"));assertEquals(70_000_000,events.getFirst().getLong("rawNs"));assertEquals(20_000_000,events.getFirst().getLong("flattenerNs"));}finally{java.nio.file.Files.deleteIfExists(file);}}
}
